        let s = "Hello, 世界!";
        let res = truncate_safe(s, 8);
        assert!(res.len() <= 8);
    }
}

use std::sync::{Arc, Mutex};

#[derive(Clone)]
pub struct ThreadSafeCounter {
    val: Arc<Mutex<u32>>,
}

impl ThreadSafeCounter {
    pub fn new() -> Self {
        Self { val: Arc::new(Mutex::new(0)) }
    }
    pub fn increment(&self) {
        let mut lock = self.val.lock().unwrap();
        *lock += 1;
    }
    pub fn get(&self) -> u32 {
        *self.val.lock().unwrap()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;
    #[test]
    fn test_concurrent_increment() {
        let counter = ThreadSafeCounter::new();
        let mut handles = vec![];
        for _ in 0..10 {
            let c = counter.clone();
            handles.push(thread::spawn(move || {
                for _ in 0..100 {
                    c.increment();
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }
        assert_eq!(counter.get(), 1000);
    }
}

