pub fn parse_csv_integers(input: &str) -> Result<Vec<i64>, String> {
    let mut nums = Vec::new();
    for token in input.split(',') {
        let trimmed = token.trim();
        if trimmed.is_empty() {
            continue;
        }
        let n = trimmed.parse::<i64>().map_err(|e| format!("Failed to parse '{}': {}", trimmed, e))?;
        nums.push(n);
    }
    Ok(nums)
}

