pub struct Node {
    val: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

pub struct BinarySearchTree {
    root: Option<Box<Node>>,
}

impl BinarySearchTree {
    pub fn new() -> Self {
        Self { root: None }
    }
    pub fn insert(&mut self, val: i32) {
        fn insert_node(node: &mut Option<Box<Node>>, val: i32) {
            match node {
                Some(n) => {
                    if val < n.val {
                        insert_node(&mut n.left, val);
                    } else if val > n.val {
                        insert_node(&mut n.right, val);
                    }
                }
                None => {
                    *node = Some(Box::new(Node { val, left: None, right: None }));
                }
            }
        }
        insert_node(&mut self.root, val);
    }
    pub fn contains(&self, val: i32) -> bool {
        fn search_node(node: &Option<Box<Node>>, val: i32) -> bool {
            match node {
                Some(n) => {
                    if val == n.val {
                        true
                    } else if val < n.val {
                        search_node(&n.left, val)
                    } else {
                        search_node(&n.right, val)
                    }
                }
                None => false,
            }
        }
        search_node(&self.root, val)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_bst() {
        let mut bst = BinarySearchTree::new();
        bst.insert(5);
