pub struct MinHeap<T> {
    data: Vec<T>,
}

impl<T: Ord> MinHeap<T> {
    pub fn new() -> Self {
        Self { data: Vec::new() }
    }
    pub fn push(&mut self, val: T) {
        self.data.push(val);
        let mut idx = self.data.len() - 1;
        while idx > 0 {
            let parent = (idx - 1) / 2;
            if self.data[idx] < self.data[parent] {
                self.data.swap(idx, parent);
                idx = parent;
            } else {
                break;
            }
        }
    }
    pub fn pop(&mut self) -> Option<T> {
        if self.data.is_empty() {
            return None;
        }
        let res = self.data.swap_remove(0);
        if !self.data.is_empty() {
            let mut idx = 0;
            while idx * 2 + 1 < self.data.len() {
                let mut smallest = idx;
                let left = idx * 2 + 1;
                let right = idx * 2 + 2;
                if self.data[left] < self.data[smallest] {
                    smallest = left;
                }
                if right < self.data.len() && self.data[right] < self.data[smallest] {
                    smallest = right;
                }
                if smallest != idx {
                    self.data.swap(idx, smallest);
                    idx = smallest;
                } else {
                    break;
                }
            }
        }
        Some(res)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_min_heap() {
        let mut h = MinHeap::new();
        h.push(10);
        h.push(3);
        h.push(7);
        h.push(1);
        assert_eq!(h.pop(), Some(1));
        assert_eq!(h.pop(), Some(3));
        assert_eq!(h.pop(), Some(7));
        assert_eq!(h.pop(), Some(10));
        assert_eq!(h.pop(), None);
    }
}

