pub fn is_match(s: &str, p: &str) -> bool {
    let s_chars: Vec<char> = s.chars().collect();
    let p_chars: Vec<char> = p.chars().collect();
    let mut dp = vec![vec![false; p_chars.len() + 1]; s_chars.len() + 1];
    dp[0][0] = true;
    for j in 1..=p_chars.len() {
        if p_chars[j - 1] == '*' && j >= 2 {
            dp[0][j] = dp[0][j - 2];
        }
    }
    for i in 1..=s_chars.len() {
        for j in 1..=p_chars.len() {
            if p_chars[j - 1] == '*' && j >= 2 {
                dp[i][j] = dp[i][j - 2]
                    || (dp[i - 1][j] && (p_chars[j - 2] == '.' || p_chars[j - 2] == s_chars[i - 1]));
            } else if p_chars[j - 1] == '.' || p_chars[j - 1] == s_chars[i - 1] {
                dp[i][j] = dp[i - 1][j - 1];
            }
        }
    }
    dp[s_chars.len()][p_chars.len()]
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_regex() {
        assert!(is_match("aa", "a*"));
        assert!(is_match("ab", ".*"));
        assert!(!is_match("mississippi", "mis*is*p*."));
    }
}

