use std::collections::VecDeque;

pub fn toposort(num_nodes: usize, edges: &[(usize, usize)]) -> Option<Vec<usize>> {
    let mut in_degree = vec![0; num_nodes];
    let mut adj = vec![vec![]; num_nodes];
    for &(u, v) in edges {
        adj[u].push(v);
        in_degree[v] += 1;
    }
    let mut queue = VecDeque::new();
    for i in 0..num_nodes {
        if in_degree[i] == 0 {
            queue.push_back(i);
        }
    }
    let mut order = Vec::new();
    while let Some(u) = queue.pop_front() {
        order.push(u);
        for &v in &adj[u] {
            in_degree[v] -= 1;
            if in_degree[v] == 0 {
                queue.push_back(v);
            }
        }
    }
    if order.len() == num_nodes {
        Some(order)
    } else {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_toposort() {
        let edges = vec![(0, 1), (0, 2), (1, 3), (2, 3)];
        let order = toposort(4, &edges).unwrap();
        assert_eq!(order.len(), 4);
        let pos = |x: usize| order.iter().position(|&n| n == x).unwrap();
        assert!(pos(0) < pos(1) && pos(0) < pos(2) && pos(1) < pos(3) && pos(2) < pos(3));
    }
}

